  "s-p26": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string line;\n    getline(cin, line);\n    bool ok = false;\n    if (line.find(' ') != string::npos && line.find(' ') > 0) {\n        int space1 = line.find(' ');\n        string rest = line.substr(space1 + 1);\n        if (rest.find(' ') != string::npos) {\n            int space2 = rest.find(' ');\n            string sign = rest.substr(0, space2);\n            string b = rest.substr(space2 + 1);\n            if ((sign == \"+\" || sign == \"-\") && b.length() > 1 && b[b.length() - 1] == 'i') ok = true;\n        }\n    }\n    if (ok) cout << \"complex number\" << endl;\n    else cout << \"not a complex number\" << endl;\n    return 0;\n}\n",
