  "s-p28": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string line;\n    getline(cin, line);\n    int space1 = line.find(' ');\n    string a = line.substr(0, space1);\n    string sign = line.substr(space1 + 1, 1);\n    string b = line.substr(space1 + 3);\n    if (sign == \"+\") sign = \"-\";\n    else sign = \"+\";\n    cout << \"conjugate: \" << a << \" \" << sign << \" \" << b << endl;\n    return 0;\n}\n",
  "s-p30": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string a, plus1, b, plus2, c, plus3, d;\n    cin >> a >> plus1 >> b >> plus2 >> c >> plus3 >> d;\n    bool format = plus1 == \"+\" && plus2 == \"+\" && plus3 == \"+\"\n        && b.length() > 1 && b[b.length() - 1] == 'i'\n        && c.length() > 1 && c[c.length() - 1] == 'j'\n        && d.length() > 1 && d[d.length() - 1] == 'k';\n    if (!format) {\n        cout << \"not a quaternion\" << endl;\n    } else {\n        double x = stod(b.substr(0, b.length() - 1));\n        double y = stod(c.substr(0, c.length() - 1));\n        double z = stod(d.substr(0, d.length() - 1));\n        if (x == 0 && y == 0 && z == 0) cout << \"real quaternion\" << endl;\n        else if (stod(a) == 0) cout << \"pure quaternion\" << endl;\n        else cout << \"quaternion\" << endl;\n    }\n    return 0;\n}\n",
  "n9-1": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string v1, v2;\n    getline(cin, v1);\n    getline(cin, v2);\n    int c1 = v1.find(',');\n    int e1 = v1.find('>');\n    int c2 = v2.find(',');\n    int e2 = v2.find('>');\n    int x1 = stoi(v1.substr(1, c1 - 1));\n    int y1 = stoi(v1.substr(c1 + 1, e1 - c1 - 1));\n    int x2 = stoi(v2.substr(1, c2 - 1));\n    int y2 = stoi(v2.substr(c2 + 1, e2 - c2 - 1));\n    cout << \"difference: <\" << x1 - x2 << \", \" << y1 - y2 << \">\" << endl;\n    return 0;\n}\n",
  "n9-2": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string v1, v2;\n    getline(cin, v1);\n    getline(cin, v2);\n    int c1 = v1.find(',');\n    int e1 = v1.find('>');\n    int c2 = v2.find(',');\n    int e2 = v2.find('>');\n    int x1 = stoi(v1.substr(1, c1 - 1));\n    int y1 = stoi(v1.substr(c1 + 1, e1 - c1 - 1));\n    int x2 = stoi(v2.substr(1, c2 - 1));\n    int y2 = stoi(v2.substr(c2 + 1, e2 - c2 - 1));\n    if (x1 * y2 - y1 * x2 == 0) cout << \"parallel\" << endl;\n    else cout << \"not parallel\" << endl;\n    return 0;\n}\n",
  "n9-3": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string z1, z2;\n    getline(cin, z1);\n    getline(cin, z2);\n    int s1 = z1.find(' ');\n    double a1 = stod(z1.substr(0, s1));\n    double b1 = stod(z1.substr(s1 + 3, z1.length() - s1 - 4));\n    if (z1[s1 + 1] == '-') b1 = -b1;\n    int s2 = z2.find(' ');\n    double a2 = stod(z2.substr(0, s2));\n    double b2 = stod(z2.substr(s2 + 3, z2.length() - s2 - 4));\n    if (z2[s2 + 1] == '-') b2 = -b2;\n    double a = a1 + a2;\n    double b = b1 + b2;\n    if (b < 0) cout << \"sum: \" << a << \" - \" << -b << \"i\" << endl;\n    else cout << \"sum: \" << a << \" + \" << b << \"i\" << endl;\n    return 0;\n}\n",
  "n9-4": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string z;\n    getline(cin, z);\n    int s = z.find(' ');\n    double a = stod(z.substr(0, s));\n    double b = stod(z.substr(s + 3, z.length() - s - 4));\n    cout << \"modulus: \" << sqrt(a * a + b * b) << endl;\n    return 0;\n}\n",
  "n9-5": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string line;\n    getline(cin, line);\n    bool ok = false;\n    if (line.length() > 0 && line[0] == '<' && line[line.length() - 1] == '>') {\n        string inside = line.substr(1, line.length() - 2);\n        if (inside.find(',') != string::npos) {\n            int c1 = inside.find(',');\n            string x = inside.substr(0, c1);\n            string rest = inside.substr(c1 + 1);\n            if (rest.find(',') != string::npos) {\n                int c2 = rest.find(',');\n                string y = rest.substr(0, c2);\n                string z = rest.substr(c2 + 1);\n                if (x.length() > 0 && y.length() > 0 && z.length() > 0 && z.find(',') == string::npos) ok = true;\n            }\n        }\n    }\n    if (ok) cout << \"correct format\" << endl;\n    else cout << \"wrong format\" << endl;\n    return 0;\n}\n",
  "n10-1": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    double a, b, c, d;\n    cin >> a >> b >> c >> d;\n    double largest = max(max(a, b), max(c, d));\n    double smallest = min(min(a, b), min(c, d));\n    cout << \"range: \" << largest - smallest << endl;\n    return 0;\n}\n",
  "n10-2": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    double m1, m2, m3, m4;\n    cin >> m1 >> m2 >> m3 >> m4;\n    double lowest = min(min(m1, m2), min(m3, m4));\n    cout << \"average of the best three: \" << (m1 + m2 + m3 + m4 - lowest) / 3 << endl;\n    return 0;\n}\n",
  "n10-3": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    double coursework, exam;\n    cin >> coursework >> exam;\n    double total = coursework * 0.4 + exam * 0.6;\n    cout << \"final mark: \" << total << endl;\n    if (total >= 50) cout << \"pass\" << endl;\n    else cout << \"fail\" << endl;\n    return 0;\n}\n",
  "n10-4": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    double a, b, c;\n    cin >> a >> b >> c;\n    double average = (a + b + c) / 3;\n    cout << \"average: \" << average << endl;\n    double da = a - average;\n    if (da < 0) da = -da;\n    double db = b - average;\n    if (db < 0) db = -db;\n    double dc = c - average;\n    if (dc < 0) dc = -dc;\n    double closest = a;\n    double best = da;\n    if (db < best) { closest = b; best = db; }\n    if (dc < best) { closest = c; best = dc; }\n    cout << \"closest to the average: \" << closest << endl;\n    return 0;\n}\n",
  "n10-5": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    double a, b, c, d;\n    cin >> a >> b >> c >> d;\n    double average = (a + b + c + d) / 4;\n    double variance = (pow(a - average, 2) + pow(b - average, 2) + pow(c - average, 2) + pow(d - average, 2)) / 4;\n    cout << \"the average is: \" << average << endl;\n    cout << \"the standard deviation is: \" << sqrt(variance) << endl;\n    return 0;\n}\n",
  "s-l6-e1": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    float lft;\n    cout << \"Enter the length in feet: \";\n    cin >> lft;\n    float lcm = lft * 30;\n    cout << \"The length in cm is \" << lcm << endl;\n    return 0;\n}\n",
