  "s-w9-p10": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int k = 1;\n    int x;\n    int sum = 0;\n    while (k <= 50) {\n        cin >> x;\n        sum = sum + x;\n        k++;\n    }\n    cout << \"sum: \" << sum << endl;\n    cout << \"average: \" << sum / 50.0 << endl;\n    return 0;\n}\n",
  "s-w9-p11": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int count;\n    cin >> count;\n    float value, sum = 0;\n    int k = 1;\n    while (k <= count) {\n        cin >> value;\n        sum = sum + value;\n        k++;\n    }\n    cout << \"average: \" << sum / count << endl;\n    return 0;\n}\n",
