  "s-l8-e5": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    char c;\n    string s;\n    int occurrence = 0;\n    cout << \"please enter the sentence: \";\n    getline(cin, s);\n    cout << \"please enter the letter: \";\n    cin >> c;\n    for (int i = 0; i < s.length(); i++) {\n        if (s.at(i) == c)\n            occurrence++;\n    }\n    cout << \"The letter '\" << c;\n    cout << \"' occurred: \" << occurrence << \" times.\" << endl;\n    return 0;\n}\n",
  "n13-1": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int f = 1;\n    for (int i = 2; i <= n; i++) f = f * i;\n    cout << n << \"! = \" << f << endl;\n    return 0;\n}\n",
  "n13-2": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int vowels = 0;\n    for (int i = 0; i < s.length(); i++) {\n        char c = s[i];\n        if (c >= 'A' && c <= 'Z') c = c + 32;\n        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') vowels++;\n    }\n    cout << \"vowels: \" << vowels << endl;\n    return 0;\n}\n",
  "n13-3": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string w;\n    cin >> w;\n    bool same = true;\n    int n = w.length();\n    for (int i = 0; i < n / 2; i++) {\n        if (w[i] != w[n - 1 - i]) same = false;\n    }\n    if (same) cout << \"palindrome\" << endl;\n    else cout << \"not a palindrome\" << endl;\n    return 0;\n}\n",
  "n13-4": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    double x, sum = 0, largest = 0;\n    for (int i = 1; i <= n; i++) {\n        cin >> x;\n        sum = sum + x;\n        if (i == 1 || x > largest) largest = x;\n    }\n    cout << \"sum: \" << sum << endl;\n    cout << \"average: \" << sum / n << endl;\n    cout << \"largest: \" << largest << endl;\n    return 0;\n}\n",
  "n13-5": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a = 0, b = 1;\n    for (int i = 1; i <= n; i++) {\n        cout << a;\n        if (i < n) cout << \", \";\n        int next = a + b;\n        a = b;\n        b = next;\n    }\n    cout << endl;\n    return 0;\n}\n",
  "s-l8-e1": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string password;\n    do {\n        cout << \"Enter the password: \";\n        getline(cin, password);\n    } while (password != \"123\");\n    cout << \"Welcome!\" << endl;\n    return 0;\n}\n",
  "s-l6-try": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string password;\n    int wrong = -1;\n    do {\n        cout << \"Enter the password: \";\n        getline(cin, password);\n        wrong++;\n    } while (password != \"123\");\n    cout << \"Welcome!\" << endl;\n    cout << \"wrong tries: \" << wrong << endl;\n    return 0;\n}\n",
  "s-l8-break": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i <= 10; i++) {\n        if (i == 7) {\n            cout << \"Found 7! Breaking out of the loop early.\" << endl;\n            break;\n        }\n        cout << \"Checking number: \" << i << endl;\n    }\n    cout << \"The loop has ended.\" << endl;\n    return 0;\n}\n",
  "s-l8-continue": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i <= 10; i++) {\n        if (i == 7) {\n            cout << \"Found 7! Skipping this number.\" << endl;\n            continue;\n        }\n        cout << \"Processing number: \" << i << endl;\n    }\n    cout << \"The loop has ended naturally.\" << endl;\n    return 0;\n}\n",
  "n14-1": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    do {\n        cout << \"Enter a number from 1 to 10: \";\n        cin >> n;\n    } while (n < 1 || n > 10);\n    cout << \"you chose \" << n << endl;\n    return 0;\n}\n",
  "n14-2": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int x, sum = 0;\n    for (int i = 1; i <= 10; i++) {\n        cin >> x;\n        if (x < 0) break;\n        sum = sum + x;\n    }\n    cout << \"sum: \" << sum << endl;\n    return 0;\n}\n",
