  "n15-5": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int found = 0;\n    for (int x = 2; x <= n; x++) {\n        bool prime = true;\n        for (int d = 2; d < x; d++) {\n            if (x % d == 0) prime = false;\n        }\n        if (prime) {\n            cout << x << endl;\n            found++;\n        }\n    }\n    if (found == 0) cout << \"no primes\" << endl;\n    return 0;\n}\n",
  "m-1": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int kwh;\n    cin >> kwh;\n    float bill;\n    if (kwh <= 100) bill = kwh * 0.5;\n    else if (kwh <= 200) bill = 100 * 0.5 + (kwh - 100) * 0.75;\n    else bill = 100 * 0.5 + 100 * 0.75 + (kwh - 200) * 1.2;\n    if (bill > 200) bill = bill * 1.1;\n    cout << \"bill: \" << bill << endl;\n    return 0;\n}\n",
  "m-2": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    float total = 0;\n    for (int i = 1; i <= n; i++) {\n        float price;\n        int quantity;\n        cin >> price >> quantity;\n        total = total + price * quantity;\n    }\n    cout << \"total: \" << total << endl;\n    if (total > 500) {\n        float discount = total * 0.1;\n        cout << \"discount: \" << discount << endl;\n        cout << \"to pay: \" << total - discount << endl;\n    } else {\n        cout << \"to pay: \" << total << endl;\n    }\n    return 0;\n}\n",
  "m-3": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int even = 0, odd = 0, sum = 0;\n    for (int i = 1; i <= n; i++) {\n        int x;\n        cin >> x;\n        if (x % 2 == 0) {\n            even++;\n            sum = sum + x;\n        } else {\n            odd++;\n        }\n    }\n    cout << \"even: \" << even << endl;\n    cout << \"odd: \" << odd << endl;\n    cout << \"sum of the even numbers: \" << sum << endl;\n    return 0;\n}\n",
