  "m-5": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int letters = 0, digits = 0, spaces = 0, others = 0;\n    for (int i = 0; i < s.length(); i++) {\n        char c = s[i];\n        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) letters++;\n        else if (c >= '0' && c <= '9') digits++;\n        else if (c == ' ') spaces++;\n        else others++;\n    }\n    cout << \"letters: \" << letters << endl;\n    cout << \"digits: \" << digits << endl;\n    cout << \"spaces: \" << spaces << endl;\n    cout << \"others: \" << others << endl;\n    return 0;\n}\n",
  "m-6": "#include <iostream>\n#include <string>\n#include <cmath>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string key, answers;\n    cin >> key >> answers;\n    int score = 0;\n    string wrong = \"\";\n    for (int i = 0; i < key.length(); i++) {\n        if (answers[i] == key[i]) score++;\n        else wrong = wrong + \" \" + to_string(i + 1);\n    }\n    cout << \"score: \" << score << \"/\" << key.length() << endl;\n    if (wrong == \"\") cout << \"wrong: none\" << endl;\n    else cout << \"wrong:\" << wrong << endl;\n    return 0;\n}\n",
